sys_script_include.script:
var MediaUtils = Class.create();
MediaUtils.prototype = {
    initialize: function() {},

    refQualMedias: function() {
		var movesToBeShown = [];
        var grMedias = new GlideRecord("x_1131775_netflix_media");
        grMedias.addQuery("state", "3");
        grMedias.query();

        while (grMedias.next()) {
            var grReview = new GlideRecord("x_1131775_netflix_review");
            grReview.addQuery("opened_by", gs.getUserID());
            grReview.addQuery("media", grMedias.sys_id);
			grReview.addQuery("state", "!=", "4");
			grReview.query();

			if(!grReview.next()) {
				movesToBeShown.push(grMedias.getUniqueValue());
			}
        }
		return movesToBeShown;
    },

    type: 'MediaUtils'
};
